package com.runepulse.telemetry;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("runepulse")
public interface TelemetryConfig extends Config
{
    @ConfigItem(
        keyName = "paired",
        name = "Paired",
        description = "Shows whether this client is paired"
    )
    default boolean paired()
    {
        return false;
    }

    @ConfigItem(
        keyName = "pairNow",
        name = "Pair Now",
        description = "Generate and store an API token automatically"
    )
    default boolean pairNow()
    {
        return false;
    }

    @ConfigItem(
        keyName = "trackXp",
        name = "Track XP",
        description = "Send XP baselines and XP gains"
    )
    default boolean trackXp()
    {
        return true;
    }

    @ConfigItem(
        keyName = "trackGear",
        name = "Track Gear",
        description = "Send equipped gear snapshots"
    )
    default boolean trackGear()
    {
        return true;
    }

    @ConfigItem(
        keyName = "trackBossKc",
        name = "Track Boss KC",
        description = "Send boss kill counts"
    )
    default boolean trackBossKc()
    {
        return false;
    }

    @ConfigItem(
        keyName = "publicProfile",
        name = "Public Profile",
        description = "Allow your profile to be publicly viewable"
    )
    default boolean publicProfile()
    {
        return true;
    }
}

package com.runepulse.telemetry;

import com.google.inject.Provides;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.StatChanged;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.api.events.GameStateChanged;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.api.events.ChatMessage;

@PluginDescriptor(
    name = "RunePulse",
    description = "RuneLite telemetry for XP, gear, and boss KC"
)
public class TelemetryPlugin extends Plugin
{
    @Inject
    private Client client;

    @Inject
    private TelemetryService service;

    @Inject
    private ConfigManager configManager;

    @Override
    protected void startUp()
    {
        service.syncPaired(configManager);
    }

    @Subscribe
    public void onStatChanged(StatChanged event)
    {
        service.recordXpChange(event.getSkill(), event.getXp());
    }

    @Subscribe
    public void onGameTick(GameTick tick)
    {
        service.tick(client);
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event)
    {
        if (event.getGameState() != GameState.LOGGED_IN)
        {
            service.reset();
        }
    }

    @Subscribe
    public void onChatMessage(ChatMessage event)
    {
        service.onChatMessage(event);
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event)
    {
        if (!"runepulse".equals(event.getGroup()))
        {
            return;
        }

        if ("pairNow".equals(event.getKey()) && configManager.getConfig(TelemetryConfig.class).pairNow())
        {
            service.pair(configManager);
            configManager.setConfiguration("runepulse", "pairNow", false);
        }

        if ("publicProfile".equals(event.getKey()))
        {
            service.updateVisibility(configManager.getConfig(TelemetryConfig.class).publicProfile());
        }

        if ("paired".equals(event.getKey()))
        {
            service.syncPaired(configManager);
        }
    }

    @Provides
    TelemetryConfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(TelemetryConfig.class);
    }
}

package com.runepulse.telemetry;


import com.runepulse.telemetry.model.BaselineSnapshot;
import com.runepulse.telemetry.model.BossKcSnapshot;
import com.runepulse.telemetry.model.GearItem;
import com.runepulse.telemetry.model.GearSnapshot;
import com.runepulse.telemetry.model.XpSnapshot;
import java.time.Instant;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.Skill;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemManager;
import net.runelite.client.util.Text;

public class TelemetryService
{
    private final Map<Skill, Integer> lastXp = new EnumMap<>(Skill.class);
    private final Map<Skill, Integer> buffer = new EnumMap<>(Skill.class);
    private final Map<String, Integer> bossKc = new HashMap<>();
    private boolean bossKcDirty = false;
    private Instant lastSend = Instant.EPOCH;
    private boolean baselineSent = false;
    private final ExecutorService executor = Executors.newSingleThreadExecutor();
    private static final Pattern BOSSKILL_MESSAGE_PATTERN =
        Pattern.compile("Your (.+) (?:kill|success) count is: ([0-9,]+)");

    @Inject
    private TelemetryUploader uploader;

    @Inject
    private TelemetryConfig config;

    @Inject
    private ItemManager itemManager;
    public void recordXpChange(Skill skill, int currentXp)
    {
        if (!config.trackXp())
        {
            return;
        }

        int previous = lastXp.getOrDefault(skill, currentXp);
        int delta = currentXp - previous;

        if (delta > 0)
        {
            buffer.merge(skill, delta, Integer::sum);
        }

        lastXp.put(skill, currentXp);
    }

    public void tick(Client client)
    {
        if (client.getGameState() != GameState.LOGGED_IN)
        {
            return;
        }

        if (client.getLocalPlayer() == null)
        {
            return;
        }

        if (!uploader.hasToken())
        {
            return;
        }

        if (!baselineSent && config.trackXp())
        {
            baselineSent = sendBaseline(client);
        }

        if (Instant.now().isBefore(lastSend.plusSeconds(300)))
        {
            return;
        }

        String username = client.getLocalPlayer().getName();
        if (username == null || username.isBlank())
        {
            return;
        }

        if (config.trackXp() && !buffer.isEmpty())
        {
            Map<String, Integer> xpGained = new HashMap<>();
            for (Map.Entry<Skill, Integer> entry : buffer.entrySet())
            {
                xpGained.put(entry.getKey().getName(), entry.getValue());
            }

            uploader.send(new XpSnapshot(
                username,
                Instant.now().getEpochSecond(),
                xpGained
            ));

            buffer.clear();
        }

        if (config.trackGear())
        {
            sendGear(client, username);
        }

        if (config.trackBossKc() && bossKcDirty)
        {
            uploader.sendBossKc(new BossKcSnapshot(
                username,
                Instant.now().getEpochSecond(),
                new HashMap<>(bossKc)
            ));
            bossKcDirty = false;
        }
        lastSend = Instant.now();
    }

    public void reset()
    {
        buffer.clear();
        lastXp.clear();
        lastSend = Instant.EPOCH;
        baselineSent = false;
    }

    public void pair(ConfigManager configManager)
    {
        executor.submit(() ->
        {
            String token = uploader.pair();
            if (token != null && !token.isBlank())
            {
                configManager.setConfiguration("runepulse", "apiToken", token);
                configManager.setConfiguration("runepulse", "paired", true);
            }
        });
    }

    public void syncPaired(ConfigManager configManager)
    {
        String token = configManager.getConfiguration("runepulse", "apiToken");
        boolean paired = token != null && !token.isBlank();
        configManager.setConfiguration("runepulse", "paired", paired);
    }

    public void updateVisibility(boolean isPublic)
    {
        executor.submit(() -> uploader.sendVisibility(isPublic));
    }

    private boolean sendBaseline(Client client)
    {
        String username = client.getLocalPlayer().getName();
        if (username == null || username.isBlank())
        {
            return false;
        }

        Map<String, Integer> skills = new HashMap<>();
        buffer.clear();
        for (Skill skill : Skill.values())
        {
            int xp = client.getSkillExperience(skill);
            skills.put(skill.getName(), xp);
            lastXp.put(skill, xp);
        }

        uploader.sendBaseline(new BaselineSnapshot(
            username,
            Instant.now().getEpochSecond(),
            skills
        ));

        return true;
    }

    private void sendGear(Client client, String username)
    {
        ItemContainer equipment = client.getItemContainer(InventoryID.EQUIPMENT);
        if (equipment == null)
        {
            return;
        }

        Map<String, GearItem> slots = new HashMap<>();
        Map<String, Integer> slotMap = new HashMap<>();
        slotMap.put("HEAD", EquipmentInventorySlot.HEAD.getSlotIdx());
        slotMap.put("CAPE", EquipmentInventorySlot.CAPE.getSlotIdx());
        slotMap.put("AMULET", EquipmentInventorySlot.AMULET.getSlotIdx());
        slotMap.put("WEAPON", EquipmentInventorySlot.WEAPON.getSlotIdx());
        slotMap.put("BODY", EquipmentInventorySlot.BODY.getSlotIdx());
        slotMap.put("SHIELD", EquipmentInventorySlot.SHIELD.getSlotIdx());
        slotMap.put("LEGS", EquipmentInventorySlot.LEGS.getSlotIdx());
        slotMap.put("HANDS", EquipmentInventorySlot.GLOVES.getSlotIdx());
        slotMap.put("FEET", EquipmentInventorySlot.BOOTS.getSlotIdx());
        slotMap.put("RING", EquipmentInventorySlot.RING.getSlotIdx());
        slotMap.put("AMMO", 13);

        Item[] items = equipment.getItems();
        for (Map.Entry<String, Integer> entry : slotMap.entrySet())
        {
            int idx = entry.getValue();
            if (idx < 0 || idx >= items.length)
            {
                continue;
            }

            Item item = items[idx];
            if (item == null || item.getId() <= 0)
            {
                continue;
            }

            String name = itemManager.getItemComposition(item.getId()).getName();
            slots.put(entry.getKey(), new GearItem(item.getId(), name, item.getQuantity()));
        }

        uploader.sendGear(new GearSnapshot(
            username,
            Instant.now().getEpochSecond(),
            slots
        ));
    }

    public void onChatMessage(net.runelite.api.events.ChatMessage event)
    {
        if (!config.trackBossKc())
        {
            return;
        }

        String typeName = event.getType().name();
        if (!"GAMEMESSAGE".equals(typeName) && !"SPAM".equals(typeName))
        {
            return;
        }

        String msg = Text.removeTags(event.getMessage());
        Matcher m = BOSSKILL_MESSAGE_PATTERN.matcher(msg);
        if (m.find())
        {
            String bossName = Text.removeTags(m.group(1));
            String kcStr = m.group(2).replace(",", "");
            try
            {
                int kc = Integer.parseInt(kcStr);
                bossKc.put(bossName, kc);
                bossKcDirty = true;
            }
            catch (NumberFormatException ignored)
            {
            }
        }
    }
}

package com.runepulse.telemetry;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import com.runepulse.telemetry.model.BaselineSnapshot;
import com.runepulse.telemetry.model.BossKcSnapshot;
import com.runepulse.telemetry.model.GearSnapshot;
import com.runepulse.telemetry.model.XpSnapshot;
import java.io.IOException;
import javax.inject.Inject;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;
import net.runelite.client.config.ConfigManager;

public class TelemetryUploader
{
    private static final MediaType JSON = MediaType.parse("application/json");
    private static final String BASE_URL = "https://runepulse-production.up.railway.app";

    @Inject
    private OkHttpClient httpClient;

    @Inject
    private Gson gson;

    @Inject
    private TelemetryConfig config;

    @Inject
    private ConfigManager configManager;

    public void send(XpSnapshot snapshot)
    {
        postJson(buildUrl("/ingest/xp"), gson.toJson(snapshot));
    }

    public void sendBaseline(BaselineSnapshot snapshot)
    {
        postJson(buildUrl("/ingest/baseline"), gson.toJson(snapshot));
    }

    public void sendGear(GearSnapshot snapshot)
    {
        postJson(buildUrl("/ingest/gear"), gson.toJson(snapshot));
    }

    public void sendBossKc(BossKcSnapshot snapshot)
    {
        postJson(buildUrl("/ingest/boss-kc"), gson.toJson(snapshot));
    }

    public void sendVisibility(boolean isPublic)
    {
        JsonObject obj = new JsonObject();
        obj.addProperty("isPublic", isPublic);
        postJson(buildUrl("/profile/visibility"), gson.toJson(obj));
    }

    public String pair()
    {
        String url = buildUrl("/pair");
        if (url == null || url.isBlank())
        {
            return null;
        }

        Request request = new Request.Builder()
            .url(url)
            .post(RequestBody.create(JSON, "{}"))
            .build();

        try (Response response = httpClient.newCall(request).execute())
        {
            if (!response.isSuccessful() || response.body() == null)
            {
                return null;
            }

            JsonObject obj = gson.fromJson(response.body().string(), JsonObject.class);
            if (obj == null || !obj.has("token"))
            {
                return null;
            }

            return obj.get("token").getAsString();
        }
        catch (IOException e)
        {
            return null;
        }
    }

    public boolean hasToken()
    {
        String token = configManager.getConfiguration("runepulse", "apiToken");
        return token != null && !token.isBlank();
    }

    private String buildUrl(String path)
    {
        String trimmed = BASE_URL;
        if (trimmed.endsWith("/"))
        {
            trimmed = trimmed.substring(0, trimmed.length() - 1);
        }

        return trimmed + path;
    }

    private void postJson(String url, String json)
    {
        if (url == null || url.isBlank())
        {
            return;
        }

        RequestBody body = RequestBody.create(JSON, json);

        Request.Builder builder = new Request.Builder()
            .url(url)
            .post(body);

        String token = configManager.getConfiguration("runepulse", "apiToken");
        if (token != null && !token.isBlank())
        {
            builder.header("Authorization", "Bearer " + token.trim());
        }

        httpClient.newCall(builder.build()).enqueue(new Callback()
        {
            @Override
            public void onFailure(Call call, IOException e)
            {
            }

            @Override
            public void onResponse(Call call, Response response) throws IOException
            {
                response.close();
            }
        });
    }
}

